//! G14 report-builder parity against the TS answers
//! (`tests/spec/analytics-writers/report-vectors.json`, regenerated by
//! `generate-report-vectors.mjs`), plus the ingestor's day/session trimming behavior.
use aac_store::report::{self, Ingestor, ReportArgs, RowsReportArgs};
use serde_json::{Map, Value};
use std::collections::{HashMap, HashSet};

fn vectors() -> Value {
    let path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../../tests/spec/analytics-writers/report-vectors.json"
    );
    let text = std::fs::read_to_string(path).expect("report-vectors.json (run the generator)");
    serde_json::from_str(&text).expect("vectors parse")
}

fn numbers(value: &Value) -> Value {
    match value {
        Value::Number(n) => serde_json::json!(n.as_f64().expect("finite vector number")),
        Value::Array(list) => Value::Array(list.iter().map(numbers).collect()),
        Value::Object(map) => Value::Object(
            map.iter()
                .map(|(k, v)| (k.clone(), numbers(v)))
                .collect::<Map<String, Value>>(),
        ),
        other => other.clone(),
    }
}

fn string_set(value: &Value) -> HashSet<String> {
    value
        .as_array()
        .map(|a| a.iter().filter_map(|v| v.as_str().map(str::to_string)).collect())
        .unwrap_or_default()
}

fn local_map(value: &Value) -> HashMap<String, Vec<Value>> {
    value
        .as_object()
        .map(|o| {
            o.iter()
                .map(|(k, v)| (k.clone(), v.as_array().cloned().unwrap_or_default()))
                .collect()
        })
        .unwrap_or_default()
}

#[test]
fn passes_match_the_ts_builder() {
    let doc = vectors();
    for case in doc["passes"].as_array().expect("passes") {
        let input = &case["input"];
        let local = local_map(&input["local"]);
        let remote = input["remote"].as_array().cloned().unwrap_or_default();
        let states = input["states"].as_array().cloned().unwrap_or_default();
        let local_complete = string_set(&input["localComplete"]);
        let scanner_owned = string_set(&input["scannerOwned"]);
        let args = ReportArgs {
            local: &local,
            remote: &remote,
            states: &states,
            window_from_ms: input["windowFromMs"].as_i64().expect("windowFromMs"),
            now: input["now"].as_i64().expect("now"),
            local_complete: &local_complete,
            scanner_owned: &scanner_owned,
        };
        let got = numbers(&Value::Array(report::build_activity_reports(&args)));
        let expected = numbers(&case["expected"]);
        assert_eq!(got, expected, "pass {}", case["name"].as_str().unwrap_or("?"));
        // The shaped reports deserialize into the typed contract the store ingests.
        let typed = report::contract_reports(&report::build_activity_reports(&args)).expect("contract reports");
        assert_eq!(typed.len(), states.len(), "pass {} report count", case["name"]);
    }
}

#[test]
fn rows_reports_match_the_ts_builder() {
    let doc = vectors();
    for case in doc["rows"].as_array().expect("rows") {
        let input = &case["input"];
        let data = input["data"].as_array().cloned().unwrap_or_default();
        let args = RowsReportArgs {
            computer: input["computer"].as_str().expect("computer"),
            tool: input["tool"].as_str().expect("tool"),
            data: &data,
            kind: input["kind"].as_str().expect("kind"),
            read_at: input["readAt"].as_i64().expect("readAt"),
            complete: input["complete"].as_bool().expect("complete"),
            unreadable_records: None,
            cause: input["cause"].as_str(),
            now: input["now"].as_i64().expect("now"),
        };
        let got = numbers(&report::rows_report(&args));
        let expected = numbers(&case["expected"]);
        assert_eq!(got, expected, "rows {}", case["name"].as_str().unwrap_or("?"));
        report::contract_reports(&[report::rows_report(&args)]).expect("contract report");
    }
}

#[test]
fn ingestor_trims_unchanged_days_and_sessions() {
    let doc = vectors();
    let case = &doc["passes"][0];
    let input = &case["input"];
    let local = local_map(&input["local"]);
    let remote = input["remote"].as_array().cloned().unwrap_or_default();
    let states = input["states"].as_array().cloned().unwrap_or_default();
    let local_complete = string_set(&input["localComplete"]);
    let scanner_owned = string_set(&input["scannerOwned"]);
    let args = ReportArgs {
        local: &local,
        remote: &remote,
        states: &states,
        window_from_ms: input["windowFromMs"].as_i64().unwrap(),
        now: input["now"].as_i64().unwrap(),
        local_complete: &local_complete,
        scanner_owned: &scanner_owned,
    };
    let reports = report::build_activity_reports(&args);
    let mut ingestor = Ingestor::new();

    // First pass: everything is sent, no sameDays.
    let (first, remember) = ingestor.trim(&reports);
    assert!(first.iter().all(|r| r.get("sameDays").is_none()));
    let first_cells: usize = first
        .iter()
        .map(|r| r["cells"].as_array().map(Vec::len).unwrap_or(0))
        .sum();
    assert!(first_cells > 0, "first pass sends cells");
    ingestor.accept(remember, &HashSet::new());

    // Identical second pass: every day is unchanged, cells dropped, sameDays named.
    let (second, remember) = ingestor.trim(&reports);
    for r in &second {
        assert_eq!(r["cells"].as_array().map(Vec::len), Some(0), "unchanged cells dropped");
        assert!(r["sameDays"].as_array().is_some_and(|d| !d.is_empty()));
    }
    ingestor.accept(remember, &HashSet::new());

    // A refused report forgets its key: the next pass sends its cells again.
    let (third, remember) = ingestor.trim(&reports);
    ingestor.accept(remember, &HashSet::from([0]));
    let (fourth, _) = ingestor.trim(&reports);
    let fourth_cells: usize = fourth[0]["cells"].as_array().map(Vec::len).unwrap_or(0);
    assert!(fourth_cells > 0, "refused source resent");
    let _ = third;
}
